package com.codeguardian.service.cache; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.security.*; @Service public class SemanticFingerprintService{public String exact(String code){return hash(normalize(code));}public String similar(String code){String n=normalize(code).replaceAll("\"[^\"]*\"|\\b\\d+\\b","?").replaceAll("\\b[a-zA-Z_][a-zA-Z0-9_]*\\b","id");return hash(n);}private String normalize(String c){return(c==null?"":c).replaceAll("//.*|/\\*.*?\\*/","").replaceAll("\\s+"," ").trim();}private String hash(String s){try{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(String.format("%02x",b));return out.toString();}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}
